"""Build departure boards from a timetable feed. See /app/docs."""
import csv
import io
import json
import os
import sys
from datetime import date, datetime, timedelta, timezone
from zoneinfo import ZoneInfo


def read_csv(dirname, name):
    path = os.path.join(dirname, name)
    if not os.path.exists(path):
        return []
    with open(path, "r", encoding="utf-8-sig", newline="") as f:
        text = f.read()
    reader = csv.reader(io.StringIO(text, newline=""))
    header = None
    rows = []
    for rec in reader:
        if not rec or all(c.strip() == "" for c in rec):
            continue
        if header is None:
            header = [c.strip() for c in rec]
            continue
        row = {}
        for i, h in enumerate(header):
            row[h] = rec[i].strip() if i < len(rec) else ""
        rows.append(row)
    return rows


def parse_time(s):
    h, m, sec = s.split(":")
    return int(h) * 3600 + int(m) * 60 + int(sec)


def parse_date(s):
    return date(int(s[0:4]), int(s[4:6]), int(s[6:8]))


_zones = {}


def zone(name):
    z = _zones.get(name)
    if z is None:
        z = _zones[name] = ZoneInfo(name)
    return z


def origin_utc(d, tzname):
    """Noon of d in tz, minus 12h of elapsed time, as an aware UTC datetime."""
    noon = datetime(d.year, d.month, d.day, 12, 0, 0, tzinfo=zone(tzname))
    return noon.astimezone(timezone.utc) - timedelta(hours=12)


def fmt(instant, tzname):
    return instant.astimezone(zone(tzname)).isoformat(timespec="seconds")


def service_runs(sid, d, calendar, exceptions):
    ex = exceptions.get((sid, d))
    if ex == 1:
        return True
    if ex == 2:
        return False
    c = calendar.get(sid)
    if c is None:
        return False
    if not (c["start"] <= d <= c["end"]):
        return False
    return c["days"][d.weekday()] == 1


def main():
    indir, outfile = sys.argv[1], sys.argv[2]

    with open(os.path.join(indir, "request.json"), "r", encoding="utf-8-sig") as f:
        req = json.load(f)
    dates = sorted({date.fromisoformat(s.strip()) for s in req.get("service_dates", [])})

    agencies = read_csv(indir, "agency.txt")
    first_tz = agencies[0]["agency_timezone"] if agencies else "UTC"
    agency_tz = {a["agency_id"]: a["agency_timezone"] for a in agencies}
    first_agency_id = agencies[0]["agency_id"] if agencies else ""

    stops = {s["stop_id"]: s for s in read_csv(indir, "stops.txt")}
    routes = {r["route_id"]: r for r in read_csv(indir, "routes.txt")}
    trips = {t["trip_id"]: t for t in read_csv(indir, "trips.txt")}

    calendar = {}
    weekdays = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"]
    for r in read_csv(indir, "calendar.txt"):
        calendar[r["service_id"]] = {
            "days": [int(r.get(w) or 0) for w in weekdays],
            "start": parse_date(r["start_date"]),
            "end": parse_date(r["end_date"]),
        }
    exceptions = {}
    for r in read_csv(indir, "calendar_dates.txt"):
        exceptions[(r["service_id"], parse_date(r["date"]))] = int(r["exception_type"])

    freqs = {}
    for r in read_csv(indir, "frequencies.txt"):
        freqs.setdefault(r["trip_id"], []).append(r)

    st_by_trip = {}
    for r in read_csv(indir, "stop_times.txt"):
        st_by_trip.setdefault(r["trip_id"], []).append(r)

    def board_id(stop_id):
        s = stops[stop_id]
        p = s.get("parent_station", "")
        return p if p else stop_id

    def is_board_stop(s):
        lt = s.get("location_type", "")
        lt = int(lt) if lt else 0
        if lt == 1:
            return True
        return lt == 0 and not s.get("parent_station", "")

    def board_tz(sid):
        s = stops[sid]
        return s.get("stop_timezone") or first_tz

    # Precompute per-trip stop data (independent of date)
    trip_info = {}
    for tid, rows in st_by_trip.items():
        if tid not in trips:
            continue
        rows = sorted(rows, key=lambda r: int(r["stop_sequence"]))
        n = len(rows)
        times = []
        for r in rows:
            t = r.get("departure_time") or r.get("arrival_time")
            times.append(parse_time(t) if t else None)
        known = [i for i, t in enumerate(times) if t is not None]
        for i in range(n):
            if times[i] is not None:
                continue
            b = max(k for k in known if k < i)
            a = min(k for k in known if k > i)
            times[i] = times[b] + ((times[a] - times[b]) * (i - b)) // (a - b)
        trip = trips[tid]
        route = routes[trip["route_id"]]
        label = route.get("route_short_name") or route.get("route_long_name") or ""
        last_stop = rows[-1]["stop_id"]
        last_name = stops[board_id(last_stop)]["stop_name"]
        deps = []
        for i, r in enumerate(rows):
            if i == n - 1 or r.get("pickup_type", "") == "1":
                continue
            headsign = r.get("stop_headsign") or trip.get("trip_headsign") or last_name
            st = stops[r["stop_id"]]
            deps.append((i, r["stop_id"], headsign, st.get("platform_code") or None))
        agency = route.get("agency_id") or first_agency_id
        trip_info[tid] = (times, deps, label, agency)

    boards = {}
    for sid, s in stops.items():
        if is_board_stop(s):
            for d in dates:
                boards[(sid, d)] = []

    for d in dates:
        for tid, trip in trips.items():
            if tid not in trip_info:
                continue
            if not service_runs(trip["service_id"], d, calendar, exceptions):
                continue
            times, deps, label, agency = trip_info[tid]
            origin = origin_utc(d, agency_tz[agency])
            base = times[0]

            def inst(sec):
                return origin + timedelta(seconds=sec)

            entries = []  # (idx, stop, headsign, platform, kind, t, until, headway)
            if tid in freqs:
                for w in freqs[tid]:
                    start = parse_time(w["start_time"])
                    end = parse_time(w["end_time"])
                    hw = int(w["headway_secs"])
                    if start >= end:
                        continue
                    starts = list(range(start, end, hw))
                    exact = w.get("exact_times", "") == "1"
                    for (i, stop, hs, plat) in deps:
                        off = times[i] - base
                        if exact:
                            for s0 in starts:
                                entries.append((stop, hs, plat, "scheduled", s0 + off, None, None))
                        else:
                            entries.append((stop, hs, plat, "interval", starts[0] + off,
                                            starts[-1] + off, hw))
            else:
                for (i, stop, hs, plat) in deps:
                    entries.append((stop, hs, plat, "scheduled", times[i], None, None))

            for (stop, hs, plat, kind, t, until, hw) in entries:
                bid = board_id(stop)
                key = (bid, d)
                if key not in boards:
                    continue
                tz = board_tz(bid)
                ti = inst(t)
                boards[key].append((ti, label, hs, tid, plat, {
                    "kind": kind,
                    "time": fmt(ti, tz),
                    "until": fmt(inst(until), tz) if until is not None else None,
                    "headway_secs": hw,
                    "route": label,
                    "headsign": hs,
                    "trip": tid,
                    "platform": plat,
                    "agency": agency,
                }))

    out_boards = []
    for (sid, d) in sorted(boards, key=lambda k: (k[0], k[1])):
        items = boards[(sid, d)]
        items.sort(key=lambda x: (x[0], x[1], x[2], x[3], x[4] is not None, x[4] or ""))
        out_boards.append({
            "stop_id": sid,
            "name": stops[sid]["stop_name"],
            "timezone": board_tz(sid),
            "service_date": d.isoformat(),
            "departures": [x[5] for x in items],
        })

    result = {"service_dates": [d.isoformat() for d in dates], "boards": out_boards}
    with open(outfile, "w", encoding="utf-8") as f:
        json.dump(result, f, ensure_ascii=False, indent=1)


if __name__ == "__main__":
    main()
